function _opsSetManagedComment(row, tag, on) {
  if (!row) return;
  const parts = _opsSplitComments(row.comments).filter(function (p) {
    if (p === tag) return false;
    if ((tag === OPS_TAG_SOFA1 || tag === OPS_TAG_SOFA2) && (p === OPS_TAG_SOFA1 || p === OPS_TAG_SOFA2)) return false;
    return true;
  });
  if (on) parts.push(tag);
