  const id = row && (row.aptId || '');
  const fromCache = (id && _opsRentalInfo && _opsRentalInfo[id] && _opsRentalInfo[id].houseRules) || {};
  const apt = (typeof _opsAptOf === 'function') ? _opsAptOf(row) : {};
  const base = (fromCache.base_capacity != null && fromCache.base_capacity !== '')
    ? fromCache.base_capacity
    : (apt && apt.baseCapacity);
