  const people = parseInt(row.people, 10);
  if (!isFinite(base) || base <= 0 || !isFinite(people) || people <= 0) {
    _opsSetManagedComment(row, OPS_TAG_SOFA1, false);
    _opsSetManagedComment(row, OPS_TAG_SOFA2, false);
    return;
